window.kbPageData["views/entry/k-d3bcd8051f933120"] = {"key":"entry/k-d3bcd8051f933120","state":{"route":"entry/k-d3bcd8051f933120"},"node":{"id":"k-d3bcd8051f933120","mode":"k","title":"按相对生产效率分工","type":"方法与技能","domain":"数学","reading":"","intro":"","priority":100,"aliases":["两种生产任务按相对生产效率分工可减少总工期"],"qs":["国考 2025 地市级 行测#71"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两处产能都能在两类任务间切换时，可以比较同一处产能在两类任务上的机会成本，安排优先分工。求最短工期时，还可用统一折算后的最大日产能验证工期下界。","review":{"definition":"两处产能都能在两类任务间切换时，可以比较同一处产能在两类任务上的机会成本，安排优先分工。求最短工期时，还可用统一折算后的最大日产能验证工期下界。","explanation":"40台机械需要120个A模块和80个B模块。甲少产1个B可多产2个A，乙少产1个B只能多产0.5个A，因此先让甲生产A、乙生产B。20天后A已齐，B还差40个，两车间合产8天可补齐。以1个A为1个产量单位、1个B为2个单位，甲每天最多产6个单位，乙最多产4个单位，总需求为280个单位，至少需要28天。该分工达到下界，选C。","references":[],"evidence":"甲车间每天可生产6个A模块或3个B模块，乙车间每天可生产1个A模块或2个B模块。","disposition":"练习技能","basis":"据原题和解析编释。"}},"questions":{"国考 2025 地市级 行测#71":{"paper":"国考 2025 地市级 行测","n":71,"mod":"数量关系","src":["31f401e91aef8d11365d.pdf",12],"asrc":["8cece062c7c079b53130.pdf",22],"card":"fab203eb755878da09ec0964","links":[{"id":"k-d3bcd8051f933120","role":"解题依据","why":"比较两车间在两种任务上的效率之比，可确定优先分工，一类任务做完后再调配产能。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-d3bcd8051f933120":[["国考 2025 地市级 行测#71"]]}};
